\begin{theorem}
Let $n$ be an even integer. Then $n^2$ is even.
\end{theorem}

\begin{proof}
Since $n$ is even, there exists an integer $k$ such that $n = 2k$. Then
\begin{align}
  n^2 &= (2k)^2 \\
      &= 4k^2 \\
      &= 2(2k^2).
\end{align}
Since $2k^2 \in \mathbb{Z}$, the integer $n^2$ is twice an integer, hence even.
\end{proof}
